17	    17	// Parallel /admin <-> /staff routes for the tools GRANTABLE_AREAS
18	    18	// (lib/staff-grants.ts) exposes to both portals. An ADMIN account previewing
19	    19	// /staff still receives their real ADMIN-scoped notifications (new tickets,
20	    20	// replies, etc.) and their href is baked in as /admin/... at write time —
21	    21	// correct when viewed from the admin portal, but the staff subdomain can't
22	    22	// reach /admin/* at all (see middleware.ts's portal isolation), so clicking
23	    23	// one there 404'd. Confirmed live 2026-09-03. Rewriting the DISPLAY href by
24	    24	// portal (not the stored Notification.href, which stays correct for the
25	    25	// admin side) fixes it without touching every notification-creation call
26	    26	// site — same fix applies to AdminIndicators' two hardcoded links below.
27	    27	const ADMIN_TO_STAFF_HREF: Record<string, string> = {
28	    28	  "/admin/support": "/staff/support",
29	    29	  "/admin/chat": "/staff/chat",
30	    30	  "/admin/reddit": "/staff/reddit",
31	    31	  "/admin/inbox": "/staff/inbox",
32	    32	  "/admin/clients-basic": "/staff/clients",
33	    33	  "/admin/tasks": "/staff/tasks",
34	    34	};
