36	    36	export function portalHref(href: string, isStaffPortal: boolean): string {
37	    37	  if (!isStaffPortal) return href;
38	    38	  for (const [adminPrefix, staffPrefix] of Object.entries(ADMIN_TO_STAFF_HREF)) {
39	    39	    if (href === adminPrefix || href.startsWith(`${adminPrefix}/`)) {
40	    40	      return staffPrefix + href.slice(adminPrefix.length);
41	    41	    }
42	    42	  }
43	    43	  return href;
44	    44	}
