250	   250	export function Shell({
251	   251	  nav,
252	   252	  user,
253	   253	  notifications,
254	   254	  impersonation,
255	   255	  tag,
256	   256	  indicatorAccess,
257	   257	  children,
258	   258	}: {
259	   259	  nav: NavSection[];
260	   260	  user: { name: string; email: string; role: string; balanceCents: number };
261	   261	  notifications: ShellNotification[];
262	   262	  impersonation?: { adminName: string; targetEmail: string } | null;
263	   263	  tag?: string;
264	   264	  /** Which floating attention bubbles this account can actually use — see
265	   265	   *  AdminIndicators' own doc comment. Both default true (the admin portal
266	   266	   *  never passes this; ADMIN always has full access). app/staff/layout.tsx
267	   267	   *  computes these from the EMPLOYEE's real StaffGrants. */
268	   268	  indicatorAccess?: { support?: boolean; inbox?: boolean };
269	   269	  children: React.ReactNode;
270	   270	}) {
271	   271	  const pathname = usePathname();
272	   272	  // Which portal is this Shell rendering? The admin ops layout passes tag="ops",
273	   273	  // the new employee portal (app/staff/layout.tsx) passes tag="staff", and the
274	   274	  // customer dashboard passes none. This drives which floating widgets mount:
275	   275	  // the customer portal keeps the Feedback bubble (and the live-chat bubble from
276	   276	  // the root layout), while both staff-facing portals swap them for the
277	   277	  // support + email attention indicators. (Role is NOT a reliable signal here —
278	   278	  // an ADMIN visiting /dashboard is still on the customer portal, and an ADMIN
279	   279	  // previewing /staff is still on the employee portal.)
280	   280	  const isAdminPortal = tag === "ops";
281	   281	  const isStaffPortal = tag === "staff";
282	   282	  // Full-bleed routes (the mail + calendar apps) opt out of the centered/padded
283	   283	  // main so they fill the entire content area under the header with no gap.
284	   284	  // /staff/inbox mirrors /admin/inbox (same underlying mail view, Phase 5).
285	   285	  const fullBleed =
286	   286	    pathname === "/dashboard/mail" ||
287	   287	    pathname === "/dashboard/calendar" ||
288	   288	    pathname === "/admin/inbox" ||
289	   289	    pathname === "/admin/board" ||
290	   290	    pathname === "/admin/reddit" ||
291	   291	    pathname === "/staff/inbox" ||
292	   292	    pathname === "/staff/reddit";
293	   293	  // Wide (but still centered/padded, unlike fullBleed) routes — data-table-heavy
294	   294	  // pages that were clipping real columns (Time on page/Account/Referrer) at
295	   295	  // the standard 1280px cap. Keeps the page's own section padding/spacing
296	   296	  // (fullBleed strips that entirely, which this page still relies on for its
297	   297	  // stacked stat-card/globe/table sections) while giving the traffic feed
298	   298	  // table room to actually show its columns instead of truncating them.
299	   299	  const wideContent = pathname === "/admin/visitors";
300	   300	  const [notifOpen, setNotifOpen] = useState(false);
301	   301	  const [sidebarOpen, setSidebarOpen] = useState(false);
302	   302	  // Desktop-only main-sidebar collapse. Persisted so it holds across every
303	   303	  // portal page (mail, calendar, servers…). On mobile the drawer always renders
304	   304	  // expanded — every collapse style below is gated to the `lg:` breakpoint.
305	   305	  const [collapsed, setCollapsed] = useState(false);
306	   306	  const [, startTransition] = useTransition();
307	   307	
308	   308	  useEffect(() => {
309	   309	    try {
310	   310	      if (localStorage.getItem("nxeon.portal.railCollapsed") === "1") setCollapsed(true);
311	   311	    } catch {}
312	   312	  }, []);
313	   313	  function toggleCollapsed() {
314	   314	    setCollapsed((c) => {
315	   315	      const next = !c;
316	   316	      try {
317	   317	        localStorage.setItem("nxeon.portal.railCollapsed", next ? "1" : "0");
318	   318	      } catch {}
319	   319	      return next;
320	   320	    });
321	   321	  }
322	   322	
323	   323	  /**
324	   324	   * Per-group collapse (admin portal only). Sits alongside the whole-rail
325	   325	   * collapse above but tracks each nav SECTION independently, keyed by
326	   326	   * `section.key` — a map of collapsed group keys to `true`, everything absent
327	   327	   * defaults to expanded so a first-time admin (or the customer portal, which
328	   328	   * never toggles this) sees exactly the same sidebar as before this existed.
329	   329	   * Mirrors the rail-collapse persistence pattern: hydrate once on mount,
330	   330	   * write back on every toggle, both wrapped in try/catch so a blocked or
331	   331	   * full localStorage never breaks navigation.
332	   332	   */
333	   333	  const [collapsedGroups, setCollapsedGroups] = useState<Record<string, boolean>>({});
334	   334	  useEffect(() => {
335	   335	    try {
336	   336	      const raw = localStorage.getItem("nxeon.admin.navCollapsed");
337	   337	      if (raw) setCollapsedGroups(JSON.parse(raw));
338	   338	    } catch {}
339	   339	  }, []);
340	   340	  function toggleGroup(key: string) {
341	   341	    setCollapsedGroups((prev) => {
342	   342	      const next = { ...prev, [key]: !prev[key] };
343	   343	      try {
344	   344	        localStorage.setItem("nxeon.admin.navCollapsed", JSON.stringify(next));
345	   345	      } catch {}
346	   346	      return next;
347	   347	    });
348	   348	  }
349	   349	
350	   350	  /**
351	   351	   * Publish the rail's current width so `position: fixed` chrome outside this
352	   352	   * subtree can sit beside it instead of guessing.
353	   353	   *
354	   354	   * The terminal dock hardcoded `lg:left-60` (15rem) while the rail collapses to
355	   355	   * `lg:w-[4.75rem]`, leaving a ~10rem dead gutter down the left of the terminal
356	   356	   * whenever a customer collapsed the sidebar. A CSS variable on the document
357	   357	   * element reaches the dock regardless of where it is mounted.
358	   358	   */
359	   359	  useEffect(() => {
360	   360	    document.documentElement.style.setProperty("--nx-rail-w", collapsed ? "4.75rem" : "15rem");
361	   361	  }, [collapsed]);
362	   362	
363	   363	  /**
364	   364	   * Is the mobile drawer currently a drawer at all? Below `lg` the rail is an
365	   365	   * off-canvas panel translated out of view; at `lg` and up it is the ordinary
366	   366	   * page sidebar and must never be hidden or inerted.
367	   367	   *
368	   368	   * Starts `true` (desktop) so the server render and the first client render
369	   369	   * agree, and so a JS-less or pre-hydration page never has its navigation
370	   370	   * inerted. The listener corrects it a tick later.
371	   371	   */
372	   372	  const [isDesktopRail, setIsDesktopRail] = useState(true);
373	   373	  useEffect(() => {
374	   374	    const mq = window.matchMedia("(min-width: 1024px)");
375	   375	    const sync = () => setIsDesktopRail(mq.matches);
376	   376	    sync();
377	   377	    mq.addEventListener("change", sync);
378	   378	    return () => mq.removeEventListener("change", sync);
379	   379	  }, []);
380	   380	  /**
381	   381	   * Closed, off-canvas and out of reach. The rehearsal found the closed drawer
382	   382	   * still `visibility: visible` with no `aria-hidden` and **25 focusable
383	   383	   * descendants in the tab order** — so a keyboard user on a phone tabbed
384	   384	   * through the entire hidden navigation before reaching the page.
385	   385	   */
386	   386	  const drawerHidden = !isDesktopRail && !sidebarOpen;
387	   387	
388	   388	  // Escape closes the drawer. It did nothing at all before: the drawer had no
389	   389	  // close button either (the only in-drawer button is the collapse toggle, which
390	   390	  // is `lg:flex`), so a backdrop tap was the single way out.
391	   391	  useEffect(() => {
392	   392	    if (!sidebarOpen) return;
393	   393	    const onKey = (e: KeyboardEvent) => {
394	   394	      if (e.key === "Escape") setSidebarOpen(false);
395	   395	    };
