464	    51	export function middleware(req: NextRequest) {
465	    52	  const host = (req.headers.get("host") ?? "").toLowerCase().split(":")[0];
466	    53	  const { pathname } = req.nextUrl;
467	    54	
468	    55	  const adminHosts = hostList(process.env.NXEON_ADMIN_HOSTS);
469	    56	  const staffHosts = hostList(process.env.NXEON_STAFF_HOSTS);
470	    57	  const isAdminHost = adminHosts.length > 0 && adminHosts.includes(host);
471	    58	  const isStaffHost = staffHosts.length > 0 && staffHosts.includes(host);
472	    59	
473	    60	  if (isAdminHost || isStaffHost) {
474	    61	    const ownPrefix = isAdminHost ? "/admin" : "/staff";
475	    62	    const ownLogin = isAdminHost ? "/admin/login" : "/staff/login";
476	    63	
477	    64	    if (!isUniversallyAllowed(pathname) && !pathname.startsWith(ownPrefix)) {
478	    65	      // The shared /login page (and any stray redirect to it — logout()
479	    66	      // always sends there, regardless of who's logging out) lands on this
480	    67	      // host's own dedicated login instead of 404ing a signed-out visitor.
481	    68	      if (pathname === "/login") {
482	    69	        const url = req.nextUrl.clone();
483	    70	        url.pathname = ownLogin;
484	    71	        return NextResponse.redirect(url);
485	    72	      }
486	    73	      // The bare root — where someone typing/bookmarking just the hostname
487	    74	      // lands — goes to the portal itself rather than 404ing. The admin
488	    75	      // vhost happens to have its own nginx-level `location = / return 302
489	    76	      // /admin` that already covered this there (confirmed live), but the
490	    77	      // staff vhost has no equivalent, so its root 404'd under this same
491	    78	      // isolation logic. Handling it here covers both hosts the same way
492	    79	      // regardless of nginx config: an authenticated visit shows the portal,
493	    80	      // an unauthenticated one gets bounced on to ownLogin by the layout's
494	    81	      // own existing redirect — no new auth logic needed either way.
495	    82	      if (pathname === "/") {
496	    83	        const url = req.nextUrl.clone();
497	    84	        url.pathname = ownPrefix;
498	    85	        return NextResponse.redirect(url);
499	    86	      }
500	    87	      return new NextResponse("Not found.", { status: 404 });
501	    88	    }
502	    89	  }
503	    90	
504	    91	  // Server Components have no built-in way to read the current pathname —
505	    92	  // app/admin/layout.tsx and app/staff/layout.tsx need it to special-case
506	    93	  // their own /login sub-route (public, no Shell, no auth redirect) without
507	    94	  // a redirect loop. Set on the REQUEST (not the response) so headers() in a
508	    95	  // downstream Server Component actually sees it.
