798	   420	/**
799	   421	 * Self-serve hosting cancel. Destructive + irreversible, so it demands a strong
800	   422	 * two-step confirmation: the customer must type the account's primary domain
801	   423	 * exactly before the final "Cancel account" button unlocks. On success the account
802	   424	 * flips to DELETING and the provisioner tears it down; we send the customer back to
803	   425	 * the hosting list.
804	   426	 */
805	   427	function CancelHostingAccount({ accountId, primaryDomain }: { accountId: string; primaryDomain: string }) {
806	   428	  const [open, setOpen] = useState(false);
807	   429	  const [confirmText, setConfirmText] = useState("");
808	   430	  const [busy, setBusy] = useState(false);
809	   431	  const [error, setError] = useState<string | null>(null);
810	   432	
811	   433	  const matches = confirmText.trim().toLowerCase() === primaryDomain.trim().toLowerCase();
812	   434	
813	   435	  function close() {
814	   436	    if (busy) return;
815	   437	    setOpen(false);
816	   438	    setConfirmText("");
817	   439	    setError(null);
818	   440	  }
819	   441	
820	   442	  async function submit() {
821	   443	    if (!matches || busy) return;
822	   444	    setBusy(true);
823	   445	    setError(null);
824	   446	    const res = await cancelHostingAccount(accountId);
825	   447	    if (res.error) {
826	   448	      setError(res.error);
827	   449	      setBusy(false);
828	   450	      return;
829	   451	    }
830	   452	    // Account is now DELETING — leave this page for the hosting list.
831	   453	    window.location.href = "/dashboard/hosting";
832	   454	  }
833	   455	
834	   456	  return (
835	   457	    <>
836	   458	      <button type="button" className="btn-secondary border-red-500/40 px-3 py-1.5 text-sm text-red-300 hover:bg-red-500/10" onClick={() => setOpen(true)}>
837	   459	        Cancel hosting account
838	   460	      </button>
839	   461	
840	   462	      {open && (
841	   463	        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4 backdrop-blur-sm" onClick={close}>
842	   464	          <div className="w-full max-w-md rounded-2xl border border-red-500/30 bg-navy-900 p-6 shadow-2xl" onClick={(e) => e.stopPropagation()}>
843	   465	            <h3 className="font-semibold text-red-300">Cancel hosting account</h3>
844	   466	            <p className="mt-2 text-sm text-slate-400">
845	   467	              This permanently removes <span className="font-mono text-slate-200">{primaryDomain}</span> — its files,
846	   468	              databases and sites. <span className="text-red-300">This can’t be undone and there is no backup afterwards.</span>
847	   469	            </p>
848	   470	            <label className="mt-4 block text-xs text-slate-400">
849	   471	              Type <span className="font-mono text-slate-200">{primaryDomain}</span> to confirm
850	   472	            </label>
851	   473	            <input
852	   474	              type="text"
853	   475	              autoFocus
854	   476	              value={confirmText}
855	   477	              onChange={(e) => setConfirmText(e.target.value)}
856	   478	              placeholder={primaryDomain}
857	   479	              disabled={busy}
858	   480	              className="mt-1.5 w-full rounded-lg border border-white/10 bg-white/[0.03] px-3 py-2 font-mono text-sm text-slate-100 outline-none focus:border-red-500/50"
859	   481	            />
860	   482	            {error && <p className="mt-3 text-sm text-red-300">{error}</p>}
861	   483	            <div className="mt-5 flex justify-end gap-2">
862	   484	              <button type="button" className="btn-secondary px-3 py-1.5 text-sm" onClick={close} disabled={busy}>
863	   485	                Keep account
864	   486	              </button>
865	   487	              <button
866	   488	                type="button"
867	   489	                className="rounded-lg bg-red-500/90 px-3 py-1.5 text-sm font-medium text-white transition-colors hover:bg-red-500 disabled:cursor-not-allowed disabled:opacity-40"
868	   490	                onClick={submit}
869	   491	                disabled={!matches || busy}
870	   492	              >
871	   493	                {busy ? "Cancelling…" : "Cancel account"}
872	   494	              </button>
873	   495	            </div>
874	   496	          </div>
875	   497	        </div>
876	   498	      )}
877	   499	    </>
878	   500	  );
879	   501	}
